import React, { useRef, useState, useEffect, useCallback } from 'react';
import { performOCR } from '../services/ocrService';
import { Package } from '../types';

interface ScannerProps {
  onPackageScanned: (pkg: Package) => void;
}

const Scanner: React.FC<ScannerProps> = ({ onPackageScanned }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [statusMsg, setStatusMsg] = useState('Ready to Scan');

  const startCamera = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: false,
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
      }
    } catch (err) {
      setError('Camera access denied. Please enable camera in settings.');
    }
  }, []);

  useEffect(() => {
    startCamera();
    return () => {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
    };
  }, [startCamera]);

  const captureAndScan = async () => {
    if (!videoRef.current || !canvasRef.current || isScanning) return;

    setIsScanning(true);
    setStatusMsg('Analyzing Label...');

    const context = canvasRef.current.getContext('2d');
    if (!context) return;

    canvasRef.current.width = videoRef.current.videoWidth;
    canvasRef.current.height = videoRef.current.videoHeight;
    context.drawImage(videoRef.current, 0, 0);

    const base64 = canvasRef.current.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const result = await performOCR(base64);
      const newPackage: Package = {
        id: crypto.randomUUID(),
        name: result.name,
        trackingId: result.trackingId,
        receivedAt: new Date().toISOString(),
        pickedUp: false,
      };

      onPackageScanned(newPackage);
      setStatusMsg('Scanned Successfully!');
      setTimeout(() => setStatusMsg('Ready to Scan'), 2000);
    } catch (err) {
      setStatusMsg('Scan Failed. Try Again.');
    } finally {
      setIsScanning(false);
    }
  };

  return (
    <div className="relative h-full w-full flex flex-col bg-black">
      {error ? (
        <div className="p-8 text-center flex flex-col items-center justify-center h-full">
          <p className="text-red-400 mb-4">{error}</p>
          <button 
            onClick={() => window.location.reload()}
            className="px-6 py-2 bg-slate-700 rounded-lg text-white font-bold"
          >
            Retry
          </button>
        </div>
      ) : (
        <>
          <div className="relative flex-1 overflow-hidden">
            <video 
              ref={videoRef} 
              playsInline 
              className="absolute inset-0 w-full h-full object-cover"
            />
            {/* Viewfinder overlay */}
            <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none flex items-center justify-center">
                <div className="w-full max-w-xs h-40 border-2 border-emerald-500/50 rounded-xl relative shadow-[0_0_20px_rgba(16,185,129,0.3)]">
                    <div className="absolute -top-2 -left-2 w-6 h-6 border-t-4 border-l-4 border-emerald-500"></div>
                    <div className="absolute -top-2 -right-2 w-6 h-6 border-t-4 border-r-4 border-emerald-500"></div>
                    <div className="absolute -bottom-2 -left-2 w-6 h-6 border-b-4 border-l-4 border-emerald-500"></div>
                    <div className="absolute -bottom-2 -right-2 w-6 h-6 border-b-4 border-r-4 border-emerald-500"></div>
                </div>
            </div>

            <div className="absolute top-4 left-0 right-0 flex justify-center">
              <span className={`px-4 py-1.5 rounded-full text-xs font-bold uppercase tracking-widest ${
                statusMsg.includes('Failed') ? 'bg-red-500' : 
                statusMsg.includes('Success') ? 'bg-emerald-500' : 'bg-slate-900/80'
              } text-white shadow-lg`}>
                {statusMsg}
              </span>
            </div>
          </div>

          <div className="p-6 bg-slate-900 flex flex-col items-center gap-4 safe-bottom">
            <p className="text-xs text-slate-400 text-center px-4">
              Position shipping label inside the box for auto-extraction.
            </p>
            <button
              onClick={captureAndScan}
              disabled={isScanning}
              className={`w-20 h-20 rounded-full border-4 ${isScanning ? 'border-slate-600 bg-slate-800' : 'border-emerald-500 bg-emerald-600'} flex items-center justify-center active:scale-95 transition-all shadow-xl`}
            >
              {isScanning ? (
                <div className="w-8 h-8 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <div className="w-10 h-10 text-white">
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M12,17.5C14.33,17.5 16.3,15.89 16.86,13.75H18.91C18.3,17 15.42,19.5 12,19.5C8.58,19.5 5.7,17 5.09,13.75H7.14C7.7,15.89 9.67,17.5 12,17.5M12,4.5C15.42,4.5 18.3,7 18.91,10.25H16.86C16.3,8.11 14.33,6.5 12,6.5C9.67,6.5 7.7,8.11 7.14,10.25H5.09C5.7,7 8.58,4.5 12,4.5M12,2C6.47,2 2,6.47 2,12C2,17.53 6.47,22 12,22C17.53,22 22,17.53 22,12C22,6.47 17.53,2 12,2Z" />
                  </svg>
                </div>
              )}
            </button>
          </div>
        </>
      )}
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default Scanner;

import React from 'react';
import { Package } from '../types';
import PackageCard from './PackageCard';

interface InventoryProps {
  packages: Package[];
  onPickUp: (id: string) => void;
}

const Inventory: React.FC<InventoryProps> = ({ packages, onPickUp }) => {
  const activePackages = packages
    .filter(p => !p.pickedUp)
    .sort((a, b) => new Date(b.receivedAt).getTime() - new Date(a.receivedAt).getTime());

  return (
    <div className="p-4 h-full overflow-y-auto pb-24">
      <div className="flex justify-between items-center mb-6 px-1">
        <h1 className="text-2xl font-bold text-white">Current Inventory</h1>
        <span className="bg-slate-700 px-3 py-1 rounded-full text-xs font-mono text-emerald-400">
          {activePackages.length} items
        </span>
      </div>

      {activePackages.length === 0 ? (
        <div className="mt-20 text-center flex flex-col items-center">
          <div className="w-20 h-20 bg-slate-800 rounded-full flex items-center justify-center mb-4">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" />
             </svg>
          </div>
          <p className="text-slate-500">Inventory is empty.</p>
          <p className="text-sm text-slate-600">Scan a new package to get started.</p>
        </div>
      ) : (
        activePackages.map(pkg => (
          <PackageCard key={pkg.id} pkg={pkg} onPickUp={onPickUp} />
        ))
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo } from 'react';
import { Package } from '../types';
import PackageCard from './PackageCard';

interface SearchProps {
  packages: Package[];
  onPickUp: (id: string) => void;
}

const Search: React.FC<SearchProps> = ({ packages, onPickUp }) => {
  const [query, setQuery] = useState('');

  const filteredPackages = useMemo(() => {
    if (!query.trim()) return [];
    const lowerQuery = query.toLowerCase();
    return packages.filter(p => 
      !p.pickedUp && 
      (p.name.toLowerCase().includes(lowerQuery) || p.trackingId.toLowerCase().includes(lowerQuery))
    );
  }, [packages, query]);

  return (
    <div className="p-4 h-full overflow-y-auto pb-24">
      <h1 className="text-2xl font-bold text-white mb-6 px-1">Find Package</h1>

      <div className="relative mb-8">
        <input
          autoFocus
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search name or tracking ID..."
          className="w-full bg-slate-800 border-2 border-slate-700 focus:border-emerald-500 rounded-xl px-5 py-4 text-white outline-none transition-all placeholder:text-slate-600"
        />
        <div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
        </div>
      </div>

      {query.trim() && filteredPackages.length === 0 ? (
        <div className="text-center py-10">
          <p className="text-slate-500 italic">No packages found for "{query}"</p>
        </div>
      ) : (
        <div className="space-y-3">
          {filteredPackages.map(pkg => (
            <PackageCard key={pkg.id} pkg={pkg} onPickUp={onPickUp} />
          ))}
        </div>
      )}

      {!query.trim() && (
        <div className="text-center py-20 opacity-30 select-none">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mx-auto text-slate-400 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M8 16l2.879-2.879m0 0a3 3 0 104.243-4.242 3 3 0 00-4.243 4.242zM21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <p className="text-slate-400 font-medium">Type to start searching</p>
        </div>
      )}
    </div>
  );
};

export default Search;

import React, { useState, useEffect, useCallback } from 'react';
import { Tab, Package } from './types';
import { db } from './services/db';
import Scanner from './components/Scanner';
import Inventory from './components/Inventory';
import Search from './components/Search';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('scan');
  const [packages, setPackages] = useState<Package[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Load packages on mount
  useEffect(() => {
    const loadData = async () => {
      try {
        await db.init();
        const data = await db.getAll();
        setPackages(data);
      } catch (err) {
        console.error("Failed to load IndexedDB data", err);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const handlePackageScanned = useCallback(async (pkg: Package) => {
    setPackages(prev => [...prev, pkg]);
    await db.save(pkg);
  }, []);

  const handlePickUp = useCallback(async (id: string) => {
    const updatedPackages = packages.map(p => 
      p.id === id ? { ...p, pickedUp: true } : p
    );
    setPackages(updatedPackages);
    const pkg = updatedPackages.find(p => p.id === id);
    if (pkg) await db.save(pkg);
  }, [packages]);

  if (isLoading) {
    return (
      <div className="fixed inset-0 bg-slate-900 flex items-center justify-center">
        <div className="flex flex-col items-center">
           <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4"></div>
           <p className="text-slate-400 font-medium tracking-wide">KIOSK PRO</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen max-h-screen overflow-hidden bg-slate-900">
      {/* Main Content Area */}
      <main className="flex-1 overflow-hidden">
        {activeTab === 'scan' && (
          <Scanner onPackageScanned={handlePackageScanned} />
        )}
        {activeTab === 'inventory' && (
          <Inventory packages={packages} onPickUp={handlePickUp} />
        )}
        {activeTab === 'search' && (
          <Search packages={packages} onPickUp={handlePickUp} />
        )}
      </main>

      {/* Navigation Tab Bar */}
      <nav className="h-20 bg-slate-950 border-t border-slate-800 flex items-center justify-around px-2 safe-bottom z-50">
        <button
          onClick={() => setActiveTab('scan')}
          className={`flex flex-col items-center justify-center w-20 py-2 rounded-xl transition-all ${
            activeTab === 'scan' ? 'text-emerald-400 scale-110' : 'text-slate-500'
          }`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" />
          </svg>
          <span className="text-[10px] font-bold uppercase tracking-tighter">Scan</span>
        </button>

        <button
          onClick={() => setActiveTab('inventory')}
          className={`flex flex-col items-center justify-center w-20 py-2 rounded-xl transition-all ${
            activeTab === 'inventory' ? 'text-emerald-400 scale-110' : 'text-slate-500'
          }`}
        >
          <div className="relative">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
            </svg>
            {packages.filter(p => !p.pickedUp).length > 0 && (
               <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-emerald-500 text-[9px] font-bold text-white">
                 {packages.filter(p => !p.pickedUp).length}
               </span>
            )}
          </div>
          <span className="text-[10px] font-bold uppercase tracking-tighter">Stock</span>
        </button>

        <button
          onClick={() => setActiveTab('search')}
          className={`flex flex-col items-center justify-center w-20 py-2 rounded-xl transition-all ${
            activeTab === 'search' ? 'text-emerald-400 scale-110' : 'text-slate-500'
          }`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          <span className="text-[10px] font-bold uppercase tracking-tighter">Search</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

export interface Package {
  id: string;
  name: string;
  trackingId: string;
  receivedAt: string;
  pickedUp: boolean;
  locationCode: string | null;
}

export type Tab = 'scan' | 'set-location' | 'inventory' | 'search';

export interface OCRResult {
  name: string;
  trackingId: string;
}

import React, { useRef, useState, useEffect, useCallback } from 'react';

interface LocationScannerProps {
  onLocationScanned: (code: string) => void;
  lastPackageName: string | null;
}

const LocationScanner: React.FC<LocationScannerProps> = ({ onLocationScanned, lastPackageName }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [isScanning, setIsScanning] = useState(true);

  const startCamera = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' },
        audio: false,
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
      }
    } catch (err) {
      setError('Camera access denied.');
    }
  }, []);

  useEffect(() => {
    startCamera();
    const interval = setInterval(() => {
      if (videoRef.current && canvasRef.current && isScanning) {
        const video = videoRef.current;
        const canvas = canvasRef.current;
        const context = canvas.getContext('2d');
        if (context && video.readyState === video.HAVE_ENOUGH_DATA) {
          canvas.height = video.videoHeight;
          canvas.width = video.videoWidth;
          context.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
          // @ts-ignore
          const code = window.jsQR(imageData.data, imageData.width, imageData.height, {
            inversionAttempts: "dontInvert",
          });
          if (code) {
            setIsScanning(false);
            onLocationScanned(code.data);
          }
        }
      }
    }, 200);

    return () => {
      clearInterval(interval);
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
    };
